import os
import time
import urllib.request
import urllib.error
import json
from pathlib import Path
from datetime import datetime
from typing import Optional


class DownloadNotifier:
    def __init__(
        self,
        download_url: str,
        notification_url: str,
        target_dir: str = "./target",
        interval: int = 5,
    ):
        self.download_url = download_url
        self.notification_url = notification_url
        self.target_dir = Path(target_dir)
        self.interval = interval
        self.target_dir.mkdir(parents=True, exist_ok=True)

    def download_file(self) -> Optional[str]:
        try:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"download_{timestamp}.dat"
            filepath = self.target_dir / filename


            with urllib.request.urlopen(self.download_url, timeout=5) as response:
                content = response.read()
                filepath.write_bytes(content)

            return str(filepath)

        except urllib.error.URLError as e:
            return None
        except Exception as e:
            return None

    def send_notification(self, filepath: Optional[str] = None):
        print("\n" + "=" * 60)
        print("=" * 60)

        if filepath:
        else:


        try:
            notification_data = {
                "timestamp": datetime.now().isoformat(),
                "status": "success" if filepath else "failure",
                "filepath": filepath
            }

            request = urllib.request.Request(
                self.notification_url,
                data=json.dumps(notification_data).encode('utf-8'),
                headers={'Content-Type': 'application/json'},
                method='POST'
            )

            with urllib.request.urlopen(request, timeout=5) as response:
        except urllib.error.URLError as e:
        except Exception as e:

        print("=" * 60 + "\n")

    def run(self, iterations: int = 3):

        for i in range(iterations):

            filepath = self.download_file()
            self.send_notification(filepath)

            if i < iterations - 1:
                time.sleep(self.interval)



def main():
    download_url = "https://example.com/data/file.zip"
    notification_url = "https://example.com/notifications/status"

    notifier = DownloadNotifier(
        download_url=download_url,
        notification_url=notification_url,
        target_dir="./target",
        interval=5
    )

    notifier.run(iterations=3)


if __name__ == "__main__":
    main()

