"""
Email Marketing Automation Tool (Demo Version)


"""

import smtplib
import json
import logging
import os
import time
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from pathlib import Path
from datetime import datetime
from typing import List, Dict, Any

TARGET_DIR = Path("./target")
CONFIG_FILE = TARGET_DIR / "config.json"
LOG_FILE = TARGET_DIR / "marketing_automation.log"
SERVICE_STATE_FILE = TARGET_DIR / "service_state.json"
BANNER_HTML_FILE = TARGET_DIR / "banner_ad.html"

