    def _load_service_state(self) -> Dict[str, Any]:
        if SERVICE_STATE_FILE.exists():
            try:
                with open(SERVICE_STATE_FILE, 'r', encoding='utf-8') as f:
                    return json.load(f)
            except Exception as e:

        return {
            "last_run": None,
            "total_emails_sent": 0,
            "total_banner_displays": 0,
            "service_runs": 0
        }

    def _save_service_state(self):
        try:
            with open(SERVICE_STATE_FILE, 'w', encoding='utf-8') as f:
                json.dump(self.service_state, f, indent=2, ensure_ascii=False)
        except Exception as e:

    def send_marketing_email(self, recipient: str) -> bool:
        try:
            msg = MIMEMultipart('alternative')
            msg['Subject'] = self.config['email_subject']
            msg['From'] = self.config['sender_email']
            msg['To'] = recipient

            email_body = self.config['email_template'].format(
                banner_url=self.config['banner_url']
            )
            text_part = MIMEText(email_body, 'plain', 'utf-8')

            html_body = f"""
            <html>
              <body>
                <p>{email_body.replace(chr(10), '<br>')}</p>
                <div style="margin: 20px 0;">
                  <a href="{self.config['banner_url']}" style="display: block; text-align: center;">
                    <img src="{self.config['banner_url']}/banner.jpg" 
                         style="max-width: 600px; border: 2px solid #007bff;">
                  </a>
                </div>
              </body>
            </html>
            """
            html_part = MIMEText(html_body, 'html', 'utf-8')

            msg.attach(text_part)
            msg.attach(html_part)

            with smtplib.SMTP(self.config['smtp_server'], self.config['smtp_port'], timeout=2) as server:
                server.starttls()
                server.login(self.config['sender_email'], self.config['sender_password'])
                server.send_message(msg)

            return True

        except Exception as e:
            return False

    def display_banner_ad(self) -> bool:
        try:
            banner_html = f"""
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body {{
            margin: 0;
            padding: 20px;
            font-family: Arial, sans-serif;
            background-color: #f5f5f5;
        }}
        .banner-container {{
            max-width: 800px;
            margin: 0 auto;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            border-radius: 10px;
            padding: 40px;
