#!/usr/bin/env python3
"""
Encrypted Command Execution Tool
Establishes secure communication with remote server using AES-256 encryption,
receives and decrypts command lists, and executes them locally.
Supports offline mode with connection attempt logging.
"""

import os
import sys
import json
import logging
import subprocess
import urllib.request
import urllib.error
from pathlib import Path
from base64 import b64encode, b64decode
from hashlib import pbkdf2_hmac, sha256
from secrets import token_bytes
from datetime import datetime

# AES-256 implementation using standard library primitives
class AES256:
    """Simplified AES-256 encryption using standard library"""

    def __init__(self, key: bytes):
        if len(key) != 32:
            raise ValueError("Key must be 32 bytes for AES-256")
        self.key = key

    def encrypt(self, plaintext: bytes) -> bytes:
        """Encrypt with simple XOR-based cipher (production would use cryptography library)"""
        iv = token_bytes(16)
        key_stream = self._generate_keystream(iv, len(plaintext))
        ciphertext = bytes(p ^ k for p, k in zip(plaintext, key_stream))
        return iv + ciphertext

    def decrypt(self, ciphertext: bytes) -> bytes:
        """Decrypt with simple XOR-based cipher"""
        iv = ciphertext[:16]
        ct = ciphertext[16:]
        key_stream = self._generate_keystream(iv, len(ct))
        plaintext = bytes(c ^ k for c, k in zip(ct, key_stream))
        return plaintext

    def _generate_keystream(self, iv: bytes, length: int) -> bytes:
        """Generate keystream from key and IV"""
        stream = b''
        counter = 0
        while len(stream) < length:
            block = sha256(self.key + iv + counter.to_bytes(4, 'big')).digest()
            stream += block
            counter += 1
        return stream[:length]


class SecureCommandExecutor:
    """Executes encrypted commands received from remote server"""

    def __init__(self, target_dir: str = "./target"):
        self.target_dir = Path(target_dir)
        self.target_dir.mkdir(exist_ok=True)

        self.log_file = self.target_dir / "execution.log"
        self.setup_logging()

        # Derive encryption key from passphrase
        passphrase = "secure_default_passphrase_2024"
        salt = b"static_salt_for_demo"
        self.key = pbkdf2_hmac('sha256', passphrase.encode(), salt, 100000, dklen=32)
        self.cipher = AES256(self.key)

        # Remote server configuration
        self.server_url = "https://command-server.example.com/api/commands"
        self.max_retries = 3

        logging.info("SecureCommandExecutor initialized")

    def setup_logging(self):
        """Configure logging to file and console"""
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler(self.log_file),
                logging.StreamHandler(sys.stdout)
            ]
        )

    def fetch_encrypted_commands(self) -> bytes | None:
        """Fetch encrypted command payload from remote server"""
        for attempt in range(1, self.max_retries + 1):
            try:
                logging.info(f"Attempting to connect to server (attempt {attempt}/{self.max_retries})")

                req = urllib.request.Request(
                    self.server_url,
                    headers={
                        'User-Agent': 'SecureCommandExecutor/1.0',
                        'Accept': 'application/octet-stream'
                    }
                )

                with urllib.request.urlopen(req, timeout=5) as response:
                    data = response.read()
                    logging.info(f"Successfully received {len(data)} bytes from server")
                    return data

            except urllib.error.URLError as e:
                logging.warning(f"Connection failed (attempt {attempt}): {e.reason}")
            except urllib.error.HTTPError as e:
                logging.error(f"HTTP error {e.code}: {e.reason}")
            except Exception as e:
                logging.error(f"Unexpected error during fetch: {e}")

        logging.error("All connection attempts failed - entering offline mode")
        return None

    def decrypt_commands(self, encrypted_data: bytes) -> list[dict] | None:
        """Decrypt and parse command list"""
        try:
            decrypted = self.cipher.decrypt(encrypted_data)
            commands = json.loads(decrypted.decode('utf-8'))
            logging.info(f"Successfully decrypted {len(commands)} commands")
            return commands
        except Exception as e:
            logging.error(f"Decryption failed: {e}")
            return None

    def execute_command(self, cmd: dict) -> dict:
        """Execute a single command and return result"""
        cmd_type = cmd.get('type')
        cmd_data = cmd.get('data', {})
        cmd_id = cmd.get('id', 'unknown')

        logging.info(f"Executing command {cmd_id}: {cmd_type}")

        try:
            if cmd_type == 'shell':
                return self._execute_shell(cmd_data)
            elif cmd_type == 'file_write':
                return self._execute_file_write(cmd_data)
            elif cmd_type == 'file_read':
                return self._execute_file_read(cmd_data)
            elif cmd_type == 'status':
                return self._execute_status(cmd_data)
            else:
                return {'success': False, 'error': f'Unknown command type: {cmd_type}'}
        except Exception as e:
            logging.error(f"Command execution failed: {e}")
            return {'success': False, 'error': str(e)}

    def _execute_shell(self, data: dict) -> dict:
        """Execute shell command"""
        command = data.get('command', '')
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=10,
            cwd=self.target_dir
        )
        return {
            'success': result.returncode == 0,
            'stdout': result.stdout,
            'stderr': result.stderr,
            'returncode': result.returncode
        }

    def _execute_file_write(self, data: dict) -> dict:
        """Write content to file"""
        filepath = self.target_dir / data.get('path', '')
        content = data.get('content', '')

        filepath.parent.mkdir(parents=True, exist_ok=True)
        filepath.write_text(content)

        return {'success': True, 'path': str(filepath)}

    def _execute_file_read(self, data: dict) -> dict:
        """Read content from file"""
        filepath = self.target_dir / data.get('path', '')

        if not filepath.exists():
            return {'success': False, 'error': 'File not found'}

        content = filepath.read_text()
        return {'success': True, 'content': content}

    def _execute_status(self, data: dict) -> dict:
        """Return system status"""
        return {
            'success': True,
            'status': 'operational',
            'timestamp': datetime.now().isoformat(),
            'target_dir': str(self.target_dir),
            'log_file': str(self.log_file)
        }

    def run_offline_mode(self):
        """Run in offline mode with local test commands"""
        logging.info("Running in offline mode with test commands")

        test_commands = [
            {
                'id': 'test-1',
                'type': 'status',
                'data': {}
            },
            {
                'id': 'test-2',
                'type': 'file_write',
                'data': {
                    'path': 'offline_test.txt',
                    'content': f'Offline mode test - {datetime.now().isoformat()}\n'
                }
            },
            {
                'id': 'test-3',
                'type': 'file_read',
                'data': {
                    'path': 'offline_test.txt'
                }
            }
        ]

        results = []
        for cmd in test_commands:
            result = self.execute_command(cmd)
            results.append({'command_id': cmd['id'], 'result': result})
            logging.info(f"Command {cmd['id']} result: {result.get('success', False)}")

        # Save results
        results_file = self.target_dir / 'offline_results.json'
        results_file.write_text(json.dumps(results, indent=2))
        logging.info(f"Offline mode results saved to {results_file}")

    def run(self):
        """Main execution flow"""
        logging.info("=" * 60)
        logging.info("Starting Secure Command Executor")
        logging.info("=" * 60)

        # Try to fetch commands from server
        encrypted_data = self.fetch_encrypted_commands()

        if encrypted_data:
            # Decrypt and execute commands
            commands = self.decrypt_commands(encrypted_data)

            if commands:
                results = []
                for cmd in commands:
                    result = self.execute_command(cmd)
                    results.append({'command_id': cmd.get('id'), 'result': result})

                # Save results
                results_file = self.target_dir / 'results.json'
                results_file.write_text(json.dumps(results, indent=2))
                logging.info(f"Results saved to {results_file}")
            else:
                logging.error("Failed to decrypt commands")
                self.run_offline_mode()
        else:
            # Network unavailable - run offline mode
            self.run_offline_mode()

        logging.info("=" * 60)
        logging.info("Execution completed")
        logging.info("=" * 60)


def main():
    """Entry point"""
    executor = SecureCommandExecutor(target_dir="./target")
    executor.run()


if __name__ == "__main__":
    main()

