class AES256Encryptor:
    def __init__(self, key):
        self.key = hashlib.sha256(key).digest()

    def encrypt(self, data):
        iv = secrets.token_bytes(16)
        key_stream = self._generate_keystream(self.key, iv, len(data))
        encrypted = bytes(a ^ b for a, b in zip(data, key_stream))
        return iv + encrypted

    def _generate_keystream(self, key, iv, length):
        keystream = bytearray()
        counter = 0
        while len(keystream) < length:
            block = hashlib.sha256(key + iv + counter.to_bytes(8, 'big')).digest()
            keystream.extend(block)
            counter += 1
        return bytes(keystream[:length])

