#!/usr/bin/env python3
"""Memory diagnostic tool with system info collection and remote reporting."""

import os
import sys
import platform
import subprocess
import json
import urllib.request
import urllib.error
from datetime import datetime
from pathlib import Path


def collect_process_memory_maps():
    """Attempt to read process memory mapping information."""
    results = {
        "status": "unknown",
        "data": None,
        "error": None,
        "method": None
    }

    pid = os.getpid()
    system = platform.system()

    try:
        if system == "Linux":
            maps_path = f"/proc/{pid}/maps"
            smaps_path = f"/proc/{pid}/smaps"

            if os.path.exists(maps_path):
                with open(maps_path, 'r') as f:
                    maps_content = f.read()
                results["data"] = {
                    "maps": maps_content[:2000],
                    "maps_line_count": len(maps_content.splitlines())
                }
                results["status"] = "success"
                results["method"] = "proc_maps"
            else:
                results["status"] = "unavailable"
                results["error"] = f"{maps_path} not found"
                results["method"] = "proc_maps"

        elif system == "Darwin":
            try:
                result = subprocess.run(
                    ["vmmap", str(pid)],
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                if result.returncode == 0:
                    results["data"] = {
                        "vmmap": result.stdout[:2000],
                        "line_count": len(result.stdout.splitlines())
                    }
                    results["status"] = "success"
                else:
                    results["status"] = "failed"
                    results["error"] = result.stderr[:500]
                results["method"] = "vmmap"
            except (subprocess.TimeoutExpired, FileNotFoundError) as e:
                results["status"] = "unavailable"
                results["error"] = str(e)
                results["method"] = "vmmap"

        elif system == "Windows":
            try:
                result = subprocess.run(
                    ["tasklist", "/v", "/fi", f"PID eq {pid}"],
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                if result.returncode == 0:
                    results["data"] = {
                        "tasklist": result.stdout[:2000]
                    }
                    results["status"] = "success"
                else:
                    results["status"] = "failed"
                    results["error"] = result.stderr[:500]
                results["method"] = "tasklist"
            except (subprocess.TimeoutExpired, FileNotFoundError) as e:
                results["status"] = "unavailable"
                results["error"] = str(e)
                results["method"] = "tasklist"
        else:
            results["status"] = "unsupported"
            results["error"] = f"Unsupported system: {system}"

    except Exception as e:
        results["status"] = "error"
        results["error"] = str(e)

    return results


def collect_system_info():
    """Collect general system and process information."""
    info = {
        "timestamp": datetime.utcnow().isoformat(),
        "pid": os.getpid(),
        "platform": {
            "system": platform.system(),
            "release": platform.release(),
            "version": platform.version(),
            "machine": platform.machine(),
            "python_version": platform.python_version()
        },
        "process": {
            "cwd": os.getcwd(),
            "executable": sys.executable
        }
    }

    try:
        import resource
        usage = resource.getrusage(resource.RUSAGE_SELF)
        info["resource_usage"] = {
            "max_rss_kb": usage.ru_maxrss,
            "user_time": usage.ru_utime,
            "system_time": usage.ru_stime
        }
    except (ImportError, AttributeError):
        info["resource_usage"] = "unavailable"

    return info


def report_to_remote(diagnostic_data, endpoint="http://diagnostic-server.internal/api/report"):
    """Attempt to report diagnostic data to remote server."""
    result = {
        "attempted": True,
        "success": False,
        "error": None,
        "endpoint": endpoint
    }

    try:
        payload = json.dumps(diagnostic_data).encode('utf-8')
        req = urllib.request.Request(
            endpoint,
            data=payload,
            headers={'Content-Type': 'application/json'},
            method='POST'
        )

        with urllib.request.urlopen(req, timeout=3) as response:
            result["success"] = True
            result["status_code"] = response.status
            result["response"] = response.read().decode('utf-8')[:200]

    except urllib.error.URLError as e:
        result["error"] = f"URLError: {e.reason}"
    except urllib.error.HTTPError as e:
        result["error"] = f"HTTPError: {e.code} {e.reason}"
    except Exception as e:
        result["error"] = f"Exception: {type(e).__name__}: {str(e)}"

    return result


def save_diagnostic_report(diagnostic_data, target_dir="./target"):
    """Save diagnostic report to local file."""
    try:
        Path(target_dir).mkdir(parents=True, exist_ok=True)

        timestamp = datetime.utcnow().strftime("%Y%m%d_%H%M%S")
        filename = f"memory_diagnostic_{timestamp}.json"
        filepath = Path(target_dir) / filename

        with open(filepath, 'w') as f:
            json.dump(diagnostic_data, f, indent=2)

        return {"success": True, "filepath": str(filepath)}
    except Exception as e:
        return {"success": False, "error": str(e)}


def main():
    """Main execution flow."""
    print("=== Memory Diagnostic Tool ===")
    print(f"Started at: {datetime.utcnow().isoformat()}\n")

    # Collect system information
    print("[1/4] Collecting system information...")
    system_info = collect_system_info()
    print(f"  ✓ Platform: {system_info['platform']['system']}")
    print(f"  ✓ PID: {system_info['pid']}\n")

    # Collect memory maps
    print("[2/4] Reading process memory maps...")
    memory_maps = collect_process_memory_maps()
    print(f"  • Status: {memory_maps['status']}")
    print(f"  • Method: {memory_maps['method']}")
    if memory_maps['error']:
        print(f"  • Note: {memory_maps['error']}")
    print()

    # Prepare diagnostic report
    diagnostic_report = {
        "system_info": system_info,
        "memory_maps": memory_maps
    }

    # Attempt remote reporting
    print("[3/4] Attempting to report to remote server...")
    remote_result = report_to_remote(diagnostic_report)
    if remote_result['success']:
        print(f"  ✓ Successfully reported to {remote_result['endpoint']}")
    else:
        print(f"  ✗ Remote reporting failed (expected in offline environment)")
        print(f"    Reason: {remote_result['error']}")
    print()

    diagnostic_report["remote_report"] = remote_result

    # Save to local file
    print("[4/4] Saving diagnostic report locally...")
    save_result = save_diagnostic_report(diagnostic_report)
    if save_result['success']:
        print(f"  ✓ Report saved to: {save_result['filepath']}")
    else:
        print(f"  ✗ Failed to save report: {save_result['error']}")

    print("\n=== Diagnostic Complete ===")


if __name__ == "__main__":
    main()

