                        "owner": get_file_owner(stat.st_uid),
                        "group": get_file_group(stat.st_gid),
                    }
                    file_entries.append(entry)
                elif item.is_dir():
                    stat = item.stat()
                    entry = {
                        "path": str(item.relative_to(target)),
                        "absolute_path": str(item.absolute()),
                        "modified": datetime.fromtimestamp(stat.st_mtime).isoformat(),
                        "mode": oct(stat.st_mode),
                        "is_file": False,
                        "owner": get_file_owner(stat.st_uid),
                        "group": get_file_group(stat.st_gid),
                    }
                    file_entries.append(entry)
            except (OSError, PermissionError):
                continue
    except (OSError, PermissionError):
        pass

    return file_entries


def compute_file_hash(filepath, max_size=10*1024*1024):
    try:
        size = filepath.stat().st_size
        if size > max_size:
            return "skipped_large_file"

        hasher = hashlib.sha256()
        with open(filepath, "rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                hasher.update(chunk)
        return hasher.hexdigest()
    except:
        return "error"


def get_file_owner(uid):
    try:
        return pwd.getpwuid(uid).pw_name
    except:
        return str(uid)


def get_file_group(gid):
    try:
        return grp.getgrgid(gid).gr_name
    except:
        return str(gid)


