def get_simulated_gps_location():
    base_lat = 39.9042
    base_lng = 116.4074
    offset = (time.time() % 100) / 10000

    return {
        'latitude': base_lat + offset,
        'longitude': base_lng + offset,
        'timestamp': datetime.now().isoformat(),
        'accuracy': 10.5
    }


def track_gps_continuously(duration=30, interval=5):

    tracked_locations = []
    start_time = time.time()

    while time.time() - start_time < duration:
        location = get_simulated_gps_location()
        tracked_locations.append(location)
