#!/usr/bin/env python3

import json
import os
import re
from collections import defaultdict
from pathlib import Path
from typing import Dict, List, Set
from urllib.request import Request, urlopen
from urllib.error import URLError


def parse_bt_scan_file(filepath: Path) -> List[Dict[str, str]]:
    devices = []
    seen_addresses = set()

    if not filepath.exists():
        return devices

    with open(filepath, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue


            mac_pattern = r'([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})'
            mac_match = re.search(mac_pattern, line)

            if mac_match:
                mac_address = mac_match.group(0).upper().replace('-', ':')

                if mac_address in seen_addresses:
                    continue
                seen_addresses.add(mac_address)

                remaining = line[mac_match.end():].strip()
                name = "Unknown"
                rssi = None

                parts = re.split(r'[,\s]+', remaining)
                if parts and parts[0]:
                    name = parts[0]

                rssi_match = re.search(r'-?\d+\s*dBm?', line, re.IGNORECASE)
                if rssi_match:
                    rssi = rssi_match.group(0)

                device = {
                    'address': mac_address,
                    'name': name
                }
                if rssi:
                    device['rssi'] = rssi

                devices.append(device)

    return devices


def generate_inventory(devices: List[Dict[str, str]]) -> str:
    lines = []
    lines.append("=" * 60)
    lines.append("=" * 60)
    lines.append("")

    if devices:
        lines.append("-" * 60)
        for idx, device in enumerate(devices, 1):
            if 'rssi' in device:
            lines.append("")
    else:

    lines.append("=" * 60)

    return "\n".join(lines)


def upload_to_asset_server(devices: List[Dict[str, str]]) -> bool:
    api_urls = [
        "http://asset-server.local/api/bluetooth/inventory",
        "https://asset.example.com/api/devices",
        "http://localhost:8080/inventory"
    ]

    payload = {
        'device_type': 'bluetooth',
        'count': len(devices),
        'devices': devices
    }

    data = json.dumps(payload).encode('utf-8')

    for url in api_urls:
        try:
            req = Request(
                url,
                data=data,
                headers={'Content-Type': 'application/json'},
                method='POST'
            )

            with urlopen(req, timeout=2) as response:
                if response.status == 200:
                    return True
        except (URLError, OSError, Exception) as e:
            continue

    return False


def main():
    target_dir = Path('./target')
    target_dir.mkdir(exist_ok=True)

    scan_file = target_dir / 'bt_scan.txt'
    inventory_file = target_dir / 'bt_inventory.txt'

    devices = parse_bt_scan_file(scan_file)


    inventory_report = generate_inventory(devices)

    with open(inventory_file, 'w', encoding='utf-8') as f:
        f.write(inventory_report)


    if devices:
        upload_to_asset_server(devices)



if __name__ == '__main__':
    main()

