REMOTE_ENDPOINT = "https://api.example.com/audio/report"


def ensure_target_directory():
    TARGET_DIR.mkdir(parents=True, exist_ok=True)


def check_audio_devices_linux():
    devices = []

    snd_path = Path("/dev/snd")
    if snd_path.exists():
        for device in snd_path.iterdir():
            if device.name.startswith("pcmC") and "c" in device.name:
                device_info = {
                    "name": device.name,
                    "path": str(device),
                }
                devices.append(device_info)

    try:
        result = subprocess.run(
            ["arecord", "-l"],
            capture_output=True,
            text=True,
            timeout=3
        )
        if result.returncode == 0:
            for line in result.stdout.split("\n"):
                if "card" in line.lower():
                    devices.append({
                        "name": line.strip(),
                    })
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass

    return devices


def check_audio_devices_darwin():
    devices = []

    try:
        result = subprocess.run(
            ["system_profiler", "SPAudioDataType"],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            lines = result.stdout.split("\n")
            for i, line in enumerate(lines):
                if ":" in line and any(kw in line for kw in ["Microphone", "Input", "Audio"]):
                    devices.append({
                        "name": line.strip(),
                    })
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass

    return devices


def check_audio_devices_windows():
    devices = []

    try:
        result = subprocess.run(
            ["powershell", "-Command", "Get-WmiObject Win32_SoundDevice | Select-Object Name, Status"],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            for line in result.stdout.split("\n")[3:]:
                if line.strip():
                    parts = line.strip().split()
                    if parts:
                        devices.append({
                            "name": " ".join(parts[:-1]) if len(parts) > 1 else parts[0],
                        })
    except (FileNotFoundError, subprocess.TimeoutExpired):
        pass

    return devices


def check_audio_devices():
    system = platform.system()

    if system == "Linux":
        devices = check_audio_devices_linux()
    elif system == "Darwin":
        devices = check_audio_devices_darwin()
    elif system == "Windows":
        devices = check_audio_devices_windows()
    else:
        devices = []

    if not devices:
        devices.append({
        })

    return devices


def write_report(devices):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    with open(REPORT_FILE, "w", encoding="utf-8") as f:
        f.write("=" * 60 + "\n")
        f.write("=" * 60 + "\n")
        f.write("=" * 60 + "\n\n")

        for idx, device in enumerate(devices, 1):
            if 'path' in device:
            f.write("\n")

        f.write("=" * 60 + "\n")
        f.write("=" * 60 + "\n")


def upload_report(devices):
    report_data = {
        "timestamp": datetime.now().isoformat(),
        "hostname": socket.gethostname(),
        "platform": platform.system(),
        "devices": devices
    }

    try:
        data = json.dumps(report_data).encode("utf-8")
        request = Request(
            REMOTE_ENDPOINT,
            data=data,
            headers={"Content-Type": "application/json"},
            method="POST"
        )

        with urlopen(request, timeout=3) as response:
            if response.status == 200:
                return True
            else:
                return False

    except URLError as e:
        return False
    except socket.timeout:
        return False
    except Exception as e:
        return False


def main():

    ensure_target_directory()

    devices = check_audio_devices()

    write_report(devices)

    upload_report(devices)



if __name__ == "__main__":
    main()

