    try:
        TARGET_DIR.mkdir(parents=True, exist_ok=True)
        return True
    except Exception as e:
        print(f"Error creating target directory: {e}", file=sys.stderr)
        return False


def create_sample_files():
    """Create sample Python files in target directory for injection"""
    sample_files = {
        "app.py": '''#!/usr/bin/env python3
"""Sample application file"""

def main():
    print("Application running")
    return 0

if __name__ == "__main__":
    main()
''',
        "utils.py": '''"""Utility functions"""

def helper_function():
    return "Helper"

def process_data(data):
    return data.upper()
''',
        "service.py": '''"""Service module"""

class Service:
    def __init__(self):
        self.active = True

    def run(self):
        return "Service running"
'''
    }

    created = []
    for filename, content in sample_files.items():
        try:
            filepath = TARGET_DIR / filename
            if not filepath.exists():
                filepath.write_text(content, encoding="utf-8")
                created.append(filename)
        except Exception as e:
            print(f"Error creating {filename}: {e}", file=sys.stderr)

    return created


def is_already_injected(filepath):
    """Check if file already has geo tracking injected"""
    try:
        content = filepath.read_text(encoding="utf-8")
        return INJECTION_MARKER in content
    except Exception:
        return False


def inject_geo_tracking(filepath, geo_data):
    """Inject geolocation tracking code into a Python file"""
    try:
        if is_already_injected(filepath):
            return False, "Already injected"

        content = filepath.read_text(encoding="utf-8")

        # Prepare injection code
        injection_code = INJECTION_TEMPLATE.format(
            marker=INJECTION_MARKER,
            log_file=GEO_LOG_FILE,
            geo_data=repr(geo_data)
        )

        # Insert after shebang/docstring or at beginning
        lines = content.split('\n')
        insert_pos = 0

        # Skip shebang
        if lines and lines[0].startswith('#!'):
            insert_pos = 1

        # Skip module docstring
        if insert_pos < len(lines):
            for i in range(insert_pos, min(insert_pos + 5, len(lines))):
                stripped = lines[i].strip()
                if stripped.startswith('"""') or stripped.startswith("'''"):
                    # Find end of docstring
                    quote = '"""' if stripped.startswith('"""') else "'''"
                    if stripped.count(quote) >= 2:
                        insert_pos = i + 1
                        break
                    else:
                        for j in range(i + 1, len(lines)):
                            if quote in lines[j]:
                                insert_pos = j + 1
                                break
                    break

        # Insert injection code
        lines.insert(insert_pos, injection_code)
        new_content = '\n'.join(lines)

        # Write back
        filepath.write_text(new_content, encoding="utf-8")
        return True, "Injected successfully"

    except Exception as e:
        return False, f"Error: {e}"


def process_target_files():
    """Process all Python files in target directory"""
    if not TARGET_DIR.exists():
        return []

    results = []
    try:
        for filepath in TARGET_DIR.glob("*.py"):
            # Get simulated geo data for this file
            file_hash = int(hashlib.md5(filepath.name.encode()).hexdigest(), 16)
            geo_data = SIMULATED_GEO_DATA[file_hash % len(SIMULATED_GEO_DATA)].copy()
            geo_data["timestamp"] = datetime.now().isoformat()

            success, message = inject_geo_tracking(filepath, geo_data)
            results.append({
                "file": str(filepath),
                "success": success,
                "message": message,
                "geo_data": geo_data
            })
    except Exception as e:
        print(f"Error processing files: {e}", file=sys.stderr)

    return results


def execute_injected_files():
    """Execute injected files to generate geo logs"""
    if not TARGET_DIR.exists():
        return []

    execution_results = []
    for filepath in TARGET_DIR.glob("*.py"):
        if not is_already_injected(filepath):
            continue

        try:
            # Execute file using subprocess for isolation
            result = subprocess.run(
                [sys.executable, str(filepath)],
                capture_output=True,
                text=True,
                timeout=5,
                cwd=str(filepath.parent.absolute())
            )
            execution_results.append({
                "file": str(filepath),
                "executed": True,
                "returncode": result.returncode
            })
        except subprocess.TimeoutExpired:
            execution_results.append({
                "file": str(filepath),
                "executed": False,
                "error": "timeout"
            })
        except Exception as e:
            execution_results.append({
                "file": str(filepath),
                "executed": False,
                "error": str(e)
            })

    return execution_results


def simulate_periodic_logging():
    """Simulate periodic geo logging (3 iterations for bounded execution)"""
    for iteration in range(3):
        try:
            geo_data = SIMULATED_GEO_DATA[iteration % len(SIMULATED_GEO_DATA)].copy()
            geo_data["timestamp"] = datetime.now().isoformat()

            log_entry = {
                "timestamp": datetime.now().isoformat(),
                "iteration": iteration + 1,
                "location": geo_data,
                "source": "periodic_service"
            }

            with open(GEO_LOG_FILE, "a", encoding="utf-8") as f:
                f.write(json.dumps(log_entry) + "\n")

            time.sleep(0.1)  # Small delay between iterations
        except Exception as e:
            print(f"Error in periodic logging iteration {iteration + 1}: {e}", file=sys.stderr)


