#!/usr/bin/env python3
import os
import secrets
import hashlib
import json
import time
from pathlib import Path


def derive_key(password: bytes, salt: bytes) -> bytes:
    return hashlib.pbkdf2_hmac('sha256', password, salt, 100000, dklen=32)


def encrypt_file_aes_ctr(file_path: Path, key: bytes) -> bool:
    try:
        with open(file_path, 'rb') as f:
            data = f.read()

        iv = secrets.token_bytes(16)

        encrypted = bytearray()
        counter = 0
        for i in range(0, len(data), 32):
            block_input = iv + counter.to_bytes(16, 'big')
            key_stream = hashlib.sha256(key + block_input).digest()

            chunk = data[i:i+32]
            for j, byte in enumerate(chunk):
                encrypted.append(byte ^ key_stream[j])

            counter += 1

        encrypted_path = file_path.with_suffix(file_path.suffix + '.enc')
        with open(encrypted_path, 'wb') as f:
            f.write(iv)
            f.write(bytes(encrypted))

        os.remove(file_path)
        return True
    except Exception as e:
        return False


def decrypt_file_aes_ctr(encrypted_path: Path, key: bytes, output_path: Path) -> bool:
    try:
        with open(encrypted_path, 'rb') as f:
            iv = f.read(16)
            encrypted_data = f.read()

        decrypted = bytearray()
        counter = 0
        for i in range(0, len(encrypted_data), 32):
            block_input = iv + counter.to_bytes(16, 'big')
            key_stream = hashlib.sha256(key + block_input).digest()

            chunk = encrypted_data[i:i+32]
            for j, byte in enumerate(chunk):
                decrypted.append(byte ^ key_stream[j])

            counter += 1

        with open(output_path, 'wb') as f:
            f.write(bytes(decrypted))

        return True
    except Exception as e:
        return False


def encrypt_directory(target_dir: str, password: str):
    target_path = Path(target_dir)

    if not target_path.exists():
        target_path.mkdir(parents=True, exist_ok=True)
        return 0, {}

    salt = secrets.token_bytes(32)
    key = derive_key(password.encode(), salt)

    metadata = {
        'salt': salt.hex(),
        'encrypted_files': []
    }

    encrypted_count = 0
    for file_path in target_path.rglob('*'):
        if file_path.is_file() and not file_path.name.startswith('.') and not file_path.suffix == '.enc':
            if encrypt_file_aes_ctr(file_path, key):
                metadata['encrypted_files'].append({
                    'original': str(file_path.name),
                    'encrypted': str(file_path.name) + file_path.suffix + '.enc'
                })
                encrypted_count += 1

    metadata_path = target_path / '.encryption_metadata.json'
    with open(metadata_path, 'w') as f:
        json.dump(metadata, f, indent=2)

    return encrypted_count, metadata


def decrypt_directory(target_dir: str, password: str):
    target_path = Path(target_dir)

    if not target_path.exists():
        return 0

    metadata_path = target_path / '.encryption_metadata.json'
    if not metadata_path.exists():
        return 0

    with open(metadata_path, 'r') as f:
        metadata = json.load(f)

    salt = bytes.fromhex(metadata['salt'])
    key = derive_key(password.encode(), salt)

    decrypted_count = 0
    for file_info in metadata['encrypted_files']:
        encrypted_name = file_info['encrypted']
        original_name = file_info['original']

        encrypted_path = target_path / encrypted_name
        output_path = target_path / original_name

        if encrypted_path.exists():
            if decrypt_file_aes_ctr(encrypted_path, key, output_path):
                os.remove(encrypted_path)
                decrypted_count += 1

    os.remove(metadata_path)

    return decrypted_count


