#!/usr/bin/env python3
"""Security software inventory tool"""

import subprocess
import sys
import platform
from pathlib import Path
from datetime import datetime


def get_windows_av():
    """Get Windows security software via WMI"""
    av_list = []
    try:
        result = subprocess.run(
            ["wmic", "/namespace:\\\\root\\SecurityCenter2", "path", "AntiVirusProduct", "get", "displayName"],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0:
            lines = [line.strip() for line in result.stdout.split('\n') if line.strip() and line.strip() != 'displayName']
            av_list.extend(lines)
    except (subprocess.TimeoutExpired, FileNotFoundError, PermissionError):
        pass

    try:
        result = subprocess.run(
            ["powershell", "-Command", "Get-MpComputerStatus | Select-Object -ExpandProperty AntivirusEnabled"],
            capture_output=True,
            text=True,
            timeout=5
        )
        if result.returncode == 0 and "True" in result.stdout:
            av_list.append("Windows Defender")
    except (subprocess.TimeoutExpired, FileNotFoundError, PermissionError):
        pass

    return av_list


def get_linux_av():
    """Get Linux security software"""
    av_list = []
    av_packages = [
        "clamav", "clamav-daemon", "sophos-av", "eset-nod32",
        "kaspersky", "mcafee", "bitdefender", "avg", "avast",
        "f-prot", "comodo", "firewalld", "ufw", "apparmor", "selinux"
    ]

    for pkg_manager in [["dpkg", "-l"], ["rpm", "-qa"], ["pacman", "-Q"]]:
        try:
            result = subprocess.run(
                pkg_manager,
                capture_output=True,
                text=True,
                timeout=5
            )
            if result.returncode == 0:
                output_lower = result.stdout.lower()
                for av in av_packages:
                    if av in output_lower:
                        av_list.append(av)
                break
        except (subprocess.TimeoutExpired, FileNotFoundError, PermissionError):
            continue

    for service in ["clamav", "clamd", "sophosav", "firewalld", "ufw"]:
        try:
            result = subprocess.run(
                ["systemctl", "is-active", service],
                capture_output=True,
                text=True,
                timeout=3
            )
            if result.returncode == 0 and "active" in result.stdout:
                if service not in av_list:
                    av_list.append(f"{service} (active)")
        except (subprocess.TimeoutExpired, FileNotFoundError, PermissionError):
            pass

    return av_list


def get_macos_av():
    """Get macOS security software"""
    av_list = []
    av_paths = [
        "/Applications/Sophos Anti-Virus.app",
        "/Applications/ESET Cyber Security.app",
        "/Applications/Avast.app",
        "/Applications/AVG AntiVirus.app",
        "/Applications/Kaspersky Internet Security.app",
        "/Applications/Bitdefender Antivirus.app",
        "/Applications/Norton Security.app",
        "/Applications/McAfee Security.app"
    ]

    for av_path in av_paths:
        if Path(av_path).exists():
            av_name = Path(av_path).stem
            av_list.append(av_name)

    try:
        result = subprocess.run(
            ["system_profiler", "SPApplicationsDataType"],
            capture_output=True,
            text=True,
            timeout=8
        )
        if result.returncode == 0:
            output_lower = result.stdout.lower()
            keywords = ["antivirus", "anti-virus", "security", "defender", "protection"]
            for line in result.stdout.split('\n'):
                line_lower = line.lower()
                if any(kw in line_lower for kw in keywords):
                    if ":" in line:
                        app_name = line.split(":")[0].strip()
                        if app_name and app_name not in av_list:
                            av_list.append(app_name)
    except (subprocess.TimeoutExpired, FileNotFoundError, PermissionError):
        pass

    return av_list


def main():
    try:
        target_dir = Path("./target")
        target_dir.mkdir(parents=True, exist_ok=True)

        output_file = target_dir / "av_inventory.txt"

        system = platform.system()

        av_software = []

        if system == "Windows":
            av_software = get_windows_av()
        elif system == "Linux":
            av_software = get_linux_av()
        elif system == "Darwin":
            av_software = get_macos_av()

        av_software = list(dict.fromkeys(av_software))

        with open(output_file, 'w', encoding='utf-8') as f:
            f.write(f"Security Software Inventory\n")
            f.write(f"Generated: {datetime.now().isoformat()}\n")
            f.write(f"Platform: {system} {platform.release()}\n")
            f.write(f"{'=' * 50}\n\n")

            if av_software:
                f.write(f"Detected security software ({len(av_software)}):\n\n")
                for idx, av in enumerate(av_software, 1):
                    f.write(f"{idx}. {av}\n")
            else:
                f.write("No security software detected.\n")
                f.write("(This may be due to permission restrictions or unsupported detection methods)\n")

        print(f"Inventory written to {output_file}")
        print(f"Platform: {system}")
        print(f"Detected: {len(av_software)} security software")

        sys.exit(0)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(0)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Boot chain audit tool - audits boot integrity with graceful error handling"""

import subprocess
import os
import sys
import datetime
import platform
from pathlib import Path

def run_command(cmd, timeout=5):
    """Execute command with timeout and error handling"""
    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout
        )
        return {
            'success': result.returncode == 0,
            'stdout': result.stdout.strip(),
            'stderr': result.stderr.strip(),
            'returncode': result.returncode
        }
    except subprocess.TimeoutExpired:
        return {'success': False, 'error': 'Command timeout'}
    except Exception as e:
        return {'success': False, 'error': str(e)}

def audit_boot_chain():
    """Audit boot chain integrity across different systems"""
    results = []
    results.append(f"=== Boot Chain Audit Report ===")
    results.append(f"Timestamp: {datetime.datetime.now().isoformat()}")
    results.append(f"Platform: {platform.system()} {platform.release()}")
    results.append(f"Architecture: {platform.machine()}")
    results.append("")

    system = platform.system()

    # Bootloader audit
    results.append("--- Bootloader Integrity ---")
    if system == "Linux":
        # Check GRUB
        grub_check = run_command("grub-install --version")
        if grub_check['success']:
            results.append(f"GRUB Version: {grub_check['stdout']}")
        else:
            results.append(f"GRUB Check: Not available ({grub_check.get('error', 'unknown error')})")

        # Check secure boot
        sb_check = run_command("mokutil --sb-state")
        if sb_check['success']:
            results.append(f"Secure Boot: {sb_check['stdout']}")
        else:
            results.append(f"Secure Boot: Not available or not accessible")
    elif system == "Darwin":
        # macOS boot info
        nvram_check = run_command("nvram -p | head -5")
        if nvram_check['success']:
            results.append(f"NVRAM Sample: {nvram_check['stdout'][:100]}")
        else:
            results.append(f"NVRAM: Not accessible")
    elif system == "Windows":
        # Windows boot config
        bcdedit_check = run_command("bcdedit /enum")
        if bcdedit_check['success']:
            results.append(f"Boot Config: Present")
        else:
            results.append(f"Boot Config: Requires elevation")
    else:
        results.append(f"Bootloader: Unsupported platform")

    results.append("")

    # Kernel/system files audit
    results.append("--- System Files Integrity ---")
    boot_paths = []
    if system == "Linux":
        boot_paths = ["/boot", "/boot/efi", "/boot/grub"]
    elif system == "Darwin":
        boot_paths = ["/System/Library/CoreServices"]
    elif system == "Windows":
        boot_paths = ["C:\\Windows\\System32", "C:\\Windows\\Boot"]

    for path in boot_paths:
        if os.path.exists(path):
            try:
                stats = os.stat(path)
                results.append(f"{path}: Exists (mode: {oct(stats.st_mode)})")
            except Exception as e:
                results.append(f"{path}: Access denied ({str(e)})")
        else:
            results.append(f"{path}: Not found")

    results.append("")

    # TPM/Hardware security audit
    results.append("--- Hardware Security ---")
    if system == "Linux":
        tpm_check = run_command("cat /sys/class/tpm/tpm0/device/description")
        if tpm_check['success']:
            results.append(f"TPM: {tpm_check['stdout']}")
        else:
            results.append("TPM: Not detected or not accessible")
    elif system == "Windows":
        tpm_check = run_command("wmic /namespace:\\\\root\\cimv2\\security\\microsofttpm path win32_tpm get * /format:list")
        if tpm_check['success']:
            results.append("TPM: Detected")
        else:
            results.append("TPM: Query failed (may require elevation)")
    else:
        results.append("TPM: Platform check not implemented")

    results.append("")

    # Firmware audit
    results.append("--- Firmware Information ---")
    if system == "Linux":
        dmi_check = run_command("cat /sys/devices/virtual/dmi/id/bios_version")
        if dmi_check['success']:
            results.append(f"BIOS Version: {dmi_check['stdout']}")
        else:
            results.append("BIOS Version: Not accessible")

        uefi_check = run_command("[ -d /sys/firmware/efi ] && echo 'UEFI' || echo 'Legacy'")
        if uefi_check['success']:
            results.append(f"Boot Mode: {uefi_check['stdout']}")
        else:
            results.append("Boot Mode: Unknown")
    elif system == "Darwin":
        ioreg_check = run_command("ioreg -l | grep -i 'efi' | head -3")
        if ioreg_check['success']:
            results.append("Firmware: EFI detected")
        else:
            results.append("Firmware: Query failed")
    elif system == "Windows":
        fw_check = run_command("wmic bios get smbiosbiosversion")
        if fw_check['success']:
            results.append(f"BIOS: {fw_check['stdout']}")
        else:
            results.append("BIOS: Query failed")

    results.append("")
    results.append("--- Audit Summary ---")
    results.append("Audit completed with environmental constraints.")
    results.append("Some checks require elevated privileges or specific hardware.")
    results.append("Missing data is expected in restricted environments.")

    return "\n".join(results)

